-- The Salon's own photo shoot replaces every older photo, and the POS keeps only the services
-- on the printed men's rate card (2026-11-02-men-rate-card.sql). Old services are switched
-- off, not deleted, so past bills and reports still resolve them; the owner can switch any of
-- them back on in Services. Forward-only and idempotent.

BEGIN;

-- 1. Website sections (home hero, colour, services, SEO share image) and their photo lists.
UPDATE website_content SET image_url = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(image_url, '/img/porthole.jpg', '/img/studio/mens-cut-scissors.jpg'), '/img/dryer.jpg', '/img/studio/hair-straightening.jpg'), '/img/clipper.jpg', '/img/studio/mens-cut-mirror.jpg'), '/img/lamps.jpg', '/img/studio/round-mirrors.jpg'), '/img/trolley.jpg', '/img/studio/lash-extensions.jpg'), '/img/balayage.jpg', '/img/studio/womens-cut-mirror.jpg'), '/img/colours.jpg', '/img/studio/womens-cut-detail.jpg'), '/img/scissors.jpg', '/img/studio/styling-stations.jpg'), '/img/card.jpg', '/img/studio/storefront.jpg'), metadata = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(metadata, '/img/porthole.jpg', '/img/studio/mens-cut-scissors.jpg'), '/img/dryer.jpg', '/img/studio/hair-straightening.jpg'), '/img/clipper.jpg', '/img/studio/mens-cut-mirror.jpg'), '/img/lamps.jpg', '/img/studio/round-mirrors.jpg'), '/img/trolley.jpg', '/img/studio/lash-extensions.jpg'), '/img/balayage.jpg', '/img/studio/womens-cut-mirror.jpg'), '/img/colours.jpg', '/img/studio/womens-cut-detail.jpg'), '/img/scissors.jpg', '/img/studio/styling-stations.jpg'), '/img/card.jpg', '/img/studio/storefront.jpg'), updated_at = NOW()
WHERE image_url LIKE '%/img/porthole.jpg%' OR image_url LIKE '%/img/dryer.jpg%' OR image_url LIKE '%/img/clipper.jpg%' OR image_url LIKE '%/img/lamps.jpg%' OR image_url LIKE '%/img/trolley.jpg%' OR image_url LIKE '%/img/balayage.jpg%' OR image_url LIKE '%/img/colours.jpg%' OR image_url LIKE '%/img/scissors.jpg%' OR image_url LIKE '%/img/card.jpg%' OR metadata LIKE '%/img/porthole.jpg%' OR metadata LIKE '%/img/dryer.jpg%' OR metadata LIKE '%/img/clipper.jpg%' OR metadata LIKE '%/img/lamps.jpg%' OR metadata LIKE '%/img/trolley.jpg%' OR metadata LIKE '%/img/balayage.jpg%' OR metadata LIKE '%/img/colours.jpg%' OR metadata LIKE '%/img/scissors.jpg%' OR metadata LIKE '%/img/card.jpg%';

-- 2. Gallery rows that showed an old photo now show the matching shot from the new shoot.
UPDATE website_gallery_images SET image_url = '/img/studio/mens-cut-scissors.jpg', title = 'Scissor cut', alt_text = 'Scissor cut on a man''s longer hair', description = 'Scissor cut on a man''s longer hair', category = 'Men', updated_at = NOW() WHERE image_url = '/img/porthole.jpg';
UPDATE website_gallery_images SET image_url = '/img/studio/hair-straightening.jpg', title = 'Straightening', alt_text = 'Stylist straightening a short bob with a flat iron', description = 'Stylist straightening a short bob with a flat iron', category = 'Women', updated_at = NOW() WHERE image_url = '/img/dryer.jpg';
UPDATE website_gallery_images SET image_url = '/img/studio/mens-cut-mirror.jpg', title = 'Men''s haircut', alt_text = 'Stylist cutting a man''s hair, reflected in the round mirror', description = 'Stylist cutting a man''s hair, reflected in the round mirror', category = 'Men', updated_at = NOW() WHERE image_url = '/img/clipper.jpg';
UPDATE website_gallery_images SET image_url = '/img/studio/round-mirrors.jpg', title = 'Round mirrors', alt_text = 'Backlit round mirrors and styling chairs under pendant lamps', description = 'Backlit round mirrors and styling chairs under pendant lamps', category = 'Studio', updated_at = NOW() WHERE image_url = '/img/lamps.jpg';
UPDATE website_gallery_images SET image_url = '/img/studio/lash-extensions.jpg', title = 'Lash extensions', alt_text = 'Lash extensions being applied with tweezers', description = 'Lash extensions being applied with tweezers', category = 'Nails & glam', updated_at = NOW() WHERE image_url = '/img/trolley.jpg';
UPDATE website_gallery_images SET image_url = '/img/studio/womens-cut-mirror.jpg', title = 'Women''s haircut', alt_text = 'Stylist cutting a woman''s hair at the round mirror', description = 'Stylist cutting a woman''s hair at the round mirror', category = 'Women', updated_at = NOW() WHERE image_url = '/img/balayage.jpg';
UPDATE website_gallery_images SET image_url = '/img/studio/womens-cut-detail.jpg', title = 'Finishing the ends', alt_text = 'Point cutting the ends of long hair', description = 'Point cutting the ends of long hair', category = 'Women', updated_at = NOW() WHERE image_url = '/img/colours.jpg';
UPDATE website_gallery_images SET image_url = '/img/studio/styling-stations.jpg', title = 'Styling stations', alt_text = 'Styling stations with trolleys, mirrors and product shelves', description = 'Styling stations with trolleys, mirrors and product shelves', category = 'Studio', updated_at = NOW() WHERE image_url = '/img/scissors.jpg';
UPDATE website_gallery_images SET image_url = '/img/studio/storefront.jpg', title = 'Find us', alt_text = 'The Salon & Glam Studio shopfront with its black sign, Birendranagar, Surkhet', description = 'The Salon & Glam Studio shopfront with its black sign, Birendranagar, Surkhet', category = 'Studio', updated_at = NOW() WHERE image_url = '/img/card.jpg';
DELETE FROM website_gallery_images WHERE image_url LIKE '/assets/%';

-- 3. Service pages, page SEO and articles that pointed at an old photo.
UPDATE website_service_pages SET image_url = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(image_url, '/img/porthole.jpg', '/img/studio/mens-cut-scissors.jpg'), '/img/dryer.jpg', '/img/studio/hair-straightening.jpg'), '/img/clipper.jpg', '/img/studio/mens-cut-mirror.jpg'), '/img/lamps.jpg', '/img/studio/round-mirrors.jpg'), '/img/trolley.jpg', '/img/studio/lash-extensions.jpg'), '/img/balayage.jpg', '/img/studio/womens-cut-mirror.jpg'), '/img/colours.jpg', '/img/studio/womens-cut-detail.jpg'), '/img/scissors.jpg', '/img/studio/styling-stations.jpg'), '/img/card.jpg', '/img/studio/storefront.jpg'), og_image = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(og_image, '/img/porthole.jpg', '/img/studio/mens-cut-scissors.jpg'), '/img/dryer.jpg', '/img/studio/hair-straightening.jpg'), '/img/clipper.jpg', '/img/studio/mens-cut-mirror.jpg'), '/img/lamps.jpg', '/img/studio/round-mirrors.jpg'), '/img/trolley.jpg', '/img/studio/lash-extensions.jpg'), '/img/balayage.jpg', '/img/studio/womens-cut-mirror.jpg'), '/img/colours.jpg', '/img/studio/womens-cut-detail.jpg'), '/img/scissors.jpg', '/img/studio/styling-stations.jpg'), '/img/card.jpg', '/img/studio/storefront.jpg'), updated_at = NOW()
WHERE image_url IN ('/img/porthole.jpg', '/img/dryer.jpg', '/img/clipper.jpg', '/img/lamps.jpg', '/img/trolley.jpg', '/img/balayage.jpg', '/img/colours.jpg', '/img/scissors.jpg', '/img/card.jpg') OR og_image IN ('/img/porthole.jpg', '/img/dryer.jpg', '/img/clipper.jpg', '/img/lamps.jpg', '/img/trolley.jpg', '/img/balayage.jpg', '/img/colours.jpg', '/img/scissors.jpg', '/img/card.jpg');
UPDATE website_page_seo SET og_image = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(og_image, '/img/porthole.jpg', '/img/studio/mens-cut-scissors.jpg'), '/img/dryer.jpg', '/img/studio/hair-straightening.jpg'), '/img/clipper.jpg', '/img/studio/mens-cut-mirror.jpg'), '/img/lamps.jpg', '/img/studio/round-mirrors.jpg'), '/img/trolley.jpg', '/img/studio/lash-extensions.jpg'), '/img/balayage.jpg', '/img/studio/womens-cut-mirror.jpg'), '/img/colours.jpg', '/img/studio/womens-cut-detail.jpg'), '/img/scissors.jpg', '/img/studio/styling-stations.jpg'), '/img/card.jpg', '/img/studio/storefront.jpg'), updated_at = NOW() WHERE og_image IN ('/img/porthole.jpg', '/img/dryer.jpg', '/img/clipper.jpg', '/img/lamps.jpg', '/img/trolley.jpg', '/img/balayage.jpg', '/img/colours.jpg', '/img/scissors.jpg', '/img/card.jpg');
UPDATE website_articles SET cover_image = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(cover_image, '/img/porthole.jpg', '/img/studio/mens-cut-scissors.jpg'), '/img/dryer.jpg', '/img/studio/hair-straightening.jpg'), '/img/clipper.jpg', '/img/studio/mens-cut-mirror.jpg'), '/img/lamps.jpg', '/img/studio/round-mirrors.jpg'), '/img/trolley.jpg', '/img/studio/lash-extensions.jpg'), '/img/balayage.jpg', '/img/studio/womens-cut-mirror.jpg'), '/img/colours.jpg', '/img/studio/womens-cut-detail.jpg'), '/img/scissors.jpg', '/img/studio/styling-stations.jpg'), '/img/card.jpg', '/img/studio/storefront.jpg'), updated_at = NOW() WHERE cover_image IN ('/img/porthole.jpg', '/img/dryer.jpg', '/img/clipper.jpg', '/img/lamps.jpg', '/img/trolley.jpg', '/img/balayage.jpg', '/img/colours.jpg', '/img/scissors.jpg', '/img/card.jpg');

-- 4. Services and packages from before the new rate card are switched off.
UPDATE salon_services SET is_active = FALSE, updated_at = NOW()
WHERE is_active IS TRUE
  AND name IN ('Haircut + Wash', 'Hair Colouring', 'Hair Straight', 'Piece Highlight', 'Silver Package', 'Gold Package', 'Platinum Package');

COMMIT;
